(() => {
  const W=globalThis.DraftmangoWorkspace,A=globalThis.DraftmangoAccounts,{e,icon,field,button}=W;
  const tabs=[['profile','user','Profile'],['preferences','sliders','Preferences'],['security','lock','Security'],['connections','link','Connections'],['usage','chart','Usage'],['billing','credit','Billing'],['cli','terminal','CLI devices'],['privacy','database','Data & privacy']];
  const card=(title,copy,body='',cls='')=>`<section class="settings-card ${cls}"><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}${body}</section>`;
  const row=(title,copy,control)=>`<div class="ws-setting-row"><div><strong>${title}</strong>${copy?`<p>${copy}</p>`:''}</div>${control}</div>`;
  const toggle=(label,id,checked,copy)=>row(label,copy,`<input class="ws-switch" type="checkbox" id="${id}" aria-label="${label}" ${checked?'checked':''}>`);
  function select(label,id,items,value){return `<div><label for="${id}">${label}</label><select id="${id}">${items.map(([v,text])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${text}</option>`).join('')}</select></div>`;}
  const date=value=>value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date unavailable';
  async function render(root,tab='profile'){
    if(!tabs.some(t=>t[0]===tab))tab='profile';
    root.innerHTML=`<header class="ws-page-header"><div><p class="ws-eyebrow">${icon('sliders')} YOUR WORKSPACE, YOUR WAY</p><h1>Settings</h1><p>Manage your account, make yourself at home, and keep track of your work.</p></div>${button(icon('external')+' Log out','logout')}</header><nav class="settings-tabs" aria-label="Settings sections">${tabs.map(([id,symbol,label])=>`<a href="#settings/${id}" ${tab===id?'aria-current="page"':''}>${icon(symbol)}${label}</a>`).join('')}</nav><div id="settings-content"></div><footer class="ws-page-footer"><strong>Draftmango</strong><span>A little more room to do your best work.</span></footer>`;
    const content=root.querySelector('#settings-content');const p=W.preferences,u=W.profile||A.user;
    const bind=(id,fn)=>{const b=root.querySelector('#'+id);if(b)b.addEventListener('click',async()=>{b.disabled=true;try{await fn(b);}catch(error){W.toast(error.message);}finally{b.disabled=false;}});};
    root.querySelector('[data-action=logout]').onclick=()=>A.signOut().catch(error=>W.toast(error.message));
    if(tab==='profile'){
      content.innerHTML=card('Personal profile','The details that make this workspace yours.',`<div class="profile-summary"><span class="avatar">${e((u.name||u.email)[0].toUpperCase())}</span><div><strong>${e(u.email)}</strong><p>Member since ${date(u.joinedAt)}</p></div></div><form id="profile-form">${field('Display name','display-name',u.name||'','text','maxlength="60" autocomplete="nickname"')}<div class="ws-inset"><p>${icon('user')} Account email</p><strong>${e(u.email)}</strong><small>${icon('lock')} ${u.emailVerified?'Verified email':'Email verification pending'}</small></div><p>Your email identifies this account. Changing it isn’t available here yet.</p><div class="card-actions"><span>Only visible to your account.</span><button class="button primary" type="submit">Save changes</button></div></form>`)+card('Account messages','Verification, password recovery and essential security messages are sent to your account email.',`<p>Essential account messages stay enabled. Draftmango does not currently send optional marketing or activity emails.</p><p class="muted">${A.config.emailDelivery==='local'?'Email delivery is local during development. Messages are saved in the server’s development mail folder.':'Account messages are sent to your email address.'}</p>`);
      root.querySelector('#profile-form').onsubmit=async event=>{event.preventDefault();const b=event.submitter;b.disabled=true;try{const result=await A.request('/api/accounts/profile',{method:'PATCH',body:{name:root.querySelector('#display-name').value.trim()}});W.profile=result.user;localStorage.setItem(A.key('preferences'),JSON.stringify({...W.preferences,name:result.user.name}));window.dispatchEvent(new Event('draftmango:records'));W.toast('Profile saved.');}catch(error){W.toast(error.message);}finally{b.disabled=false;}};
    }else if(tab==='preferences'){
      content.innerHTML=card('Appearance','Choose light, dark, or your device’s theme. Applied immediately.',`<div class="ws-theme-options">${['light','dark','system'].map(theme=>`<button class="button ${p.theme===theme?'selected':''}" data-theme="${theme}" aria-pressed="${p.theme===theme}">${icon(theme==='light'?'sun':theme==='dark'?'moon':'monitor')}${theme[0].toUpperCase()+theme.slice(1)}</button>`).join('')}</div>`)+card('Task notifications','Applied immediately and saved for your account.',toggle('Task completion sound','pref-sound',p.sound,'Play a short chime when an AI task finishes successfully.')+`<div class="ws-rule">${button(icon('sound')+' Preview sound','sound')}</div><p>Keep Draftmango open to receive alerts. Your browser and device sound settings still apply.</p>`)+`<form id="preferences-form">`+card('Editor preferences','A comfortable environment for your code. Saved changes apply to your source editor.',`<div class="ws-form-grid">${select('Font size','pref-font',[12,13,14,15,16,18,20].map(n=>[n,n+' px']),p.fontSize)}${select('Indentation','pref-indent',[2,4,8].map(n=>[n,n+' spaces']),p.indent)}</div><pre class="ws-code-sample"><span>1</span> const idea = "Something great";\n<span>2</span>   build(idea);</pre>${toggle('Word wrap','pref-wrap',p.wordWrap,'Keep long lines within the editor.')}${toggle('Line numbers','pref-lines',p.lineNumbers,'Show line numbers alongside your code.')}${toggle('Auto refresh preview','pref-auto',p.autoRefresh,'Apply source edits to the preview after you stop typing.')}`)+card('Workspace defaults','Used when opening a new workspace or editor.',`<div class="ws-form-grid">${select('Build level','pref-level',[['standard','Standard']],p.buildLevel)}${select('Preview size','pref-device',[['responsive','Match this screen'],['desktop','Desktop'],['tablet','Tablet'],['mobile','Mobile']],p.device)}</div><p class="muted">Standard uses the configured model. Additional build levels will be added with measured performance and costs.</p>${toggle('Reduce motion','pref-motion',p.reduceMotion,'Minimize workspace animations and transitions.')}<div class="ws-form-grid">${select('Starting layout','pref-starter',[['auto','Choose from my idea'],['custom','Blank starter'],['cafe','Café'],['portfolio','Portfolio'],['store','Store']],p.starter)}${select('Color palette','pref-color',[['auto','Match the idea'],...Object.entries(globalThis.DraftmangoModel.palettes).map(([v,d])=>[v,e(d.name)])],p.color)}</div><div class="card-actions"><button type="button" id="restore-preferences" class="button">Restore defaults</button><button class="button primary" type="submit">Save preferences</button></div>`)+`</form>`;
      root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=async()=>{try{await W.savePrefs({theme:b.dataset.theme});root.querySelectorAll('[data-theme]').forEach(n=>{n.classList.toggle('selected',n===b);n.setAttribute('aria-pressed',String(n===b));});window.dispatchEvent(new Event('draftmango:records'));}catch(error){W.toast(error.message);}});
      root.querySelector('#pref-sound').onchange=event=>W.savePrefs({sound:event.target.checked}).catch(error=>W.toast(error.message));root.querySelector('[data-action=sound]').onclick=W.chime;
      root.querySelector('#preferences-form').onsubmit=async event=>{event.preventDefault();const val=id=>root.querySelector('#pref-'+id);try{await W.savePrefs({fontSize:Number(val('font').value),indent:Number(val('indent').value),wordWrap:val('wrap').checked,lineNumbers:val('lines').checked,autoRefresh:val('auto').checked,reduceMotion:val('motion').checked,device:val('device').value,buildLevel:'standard',starter:val('starter').value,color:val('color').value});W.toast('Preferences saved.');}catch(error){W.toast(error.message);}};
      bind('restore-preferences',async()=>{await W.savePrefs(W.defaults);await render(root,tab);W.toast('Default preferences restored.');});
    }else if(tab==='security'){
      content.innerHTML=card('Sign-in methods','The methods already associated with this account.',row('Email and password',e(u.email),'<span class="ws-badge">Active</span>')+`<div class="ws-action-row"><button id="change-password" class="button">Change password</button><button id="reset-password" class="button">Send password reset</button></div><p class="muted">${A.config.emailDelivery==='local'?'Reset links are saved to the development mail folder.':''} GitHub repository access is managed separately in Connections.</p>`)+card('Active sessions','Review the browsers signed in to your account. Device names are based on the browser’s reported information.','<div id="session-list" aria-live="polite">Loading sessions…</div><div class="card-actions"><button class="button" id="revoke-others">Sign out other devices</button><button class="button" id="security-signout">Sign out</button></div><p class="muted">Draftmango’s two-factor authentication is not available yet.</p>');
      const load=async()=>{const result=await A.request('/api/accounts/sessions');if(!root.querySelector('#session-list'))return;root.querySelector('#session-list').innerHTML=result.sessions.map(s=>row(e(s.device),`${s.signedIn?'Signed in '+date(s.signedIn)+' · ':''}Expires ${date(s.expiresAt)}`,s.current?'<span class="ws-badge">This device</span>':`<button class="button" data-revoke="${e(s.id)}">Revoke</button>`)).join('')||'<p>No active sessions.</p>';root.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>W.dialog('Revoke session?',`<p>End access for this browser? Your current session stays signed in.</p>`,{label:'Revoke',submit:async()=>{await A.request('/api/accounts/sessions',{method:'POST',body:{action:'revoke',id:b.dataset.revoke}});await load();}}));};load().catch(error=>{if(root.querySelector('#session-list'))root.querySelector('#session-list').textContent=error.message;});
      bind('change-password',()=>W.dialog('Change password',`${field('Current password','old-password','','password','required autocomplete="current-password"')}${field('New password','new-password','','password','required minlength="10" maxlength="128" autocomplete="new-password"')}${field('Confirm new password','confirm-password','','password','required autocomplete="new-password"')}`,{label:'Update password',submit:async d=>{const next=d.querySelector('#new-password').value;if(next!==d.querySelector('#confirm-password').value)throw new Error('The new passwords do not match.');await A.request('/api/accounts/password',{method:'POST',body:{currentPassword:d.querySelector('#old-password').value,password:next}});W.toast('Password updated.');await load();}}));
      bind('reset-password',async()=>{const result=await A.request('/api/accounts/reset',{method:'POST',body:{email:u.email}});W.toast(result.emailDelivery==='local'?'Reset link saved in the local development mail folder.':'Check your email for the reset link.');});
      bind('revoke-others',()=>W.dialog('Sign out other devices?',`<p>All other browser sessions will end. This device will remain signed in.</p>`,{label:'Sign out other devices',submit:async()=>{await A.request('/api/accounts/sessions',{method:'POST',body:{action:'others'}});await load();}}));bind('security-signout',()=>A.signOut());
    }else if(tab==='connections'){
      content.innerHTML=card('Connected apps','Choose which services Draftmango can work with.',`<div class="ws-setting-row"><div><h3>${icon('code')} GitHub</h3><p>Bring repositories into your development workflow.</p></div><span class="ws-badge">Not connected</span></div><div class="ws-key-values"><div><span>Account</span><strong>No account connected</strong></div><div><span>App installations</span><strong>0</strong></div></div><div class="ws-action-row"><button class="button primary" id="connect-github">Connect GitHub</button><button class="button" id="import-github">Import public repository</button></div><p>Connecting a repository is separate from signing in with GitHub. Private repository access requires a configured Draftmango GitHub App.</p>`)+card('AI connection','Your current website generation provider.',`<div id="ai-status" role="status">Checking connection…</div><div class="card-actions"><span>Your API key stays on the server.</span><button class="button" id="refresh-ai">Refresh status</button></div>`)+card('Domains','Find a domain, review prices, or connect an address you own.',`<a class="button" href="#domains">Manage domains ${icon('arrow')}</a>`);
      bind('connect-github',()=>W.unavailable('Connect GitHub','Private repository access needs a Draftmango GitHub App. This installation has no GitHub App configured yet. You can import public repositories or source files now.'));bind('import-github',W.githubImport);
      const status=async()=>{const response=await fetch('/api/ai/status');if(!response.ok)throw new Error('AI status is unavailable.');const result=await response.json();const node=root.querySelector('#ai-status');if(node)node.textContent=result.configured?`${result.name} · ${result.model} · Configured`:'No API key configured.';};bind('refresh-ai',status);status().catch(error=>W.toast(error.message));
    }else if(tab==='usage'){
      const now=new Date(),months=Array.from({length:12},(_,i)=>{const d=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-i,1));return[d.toISOString().slice(0,7),d.toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:'UTC'})];});
      content.innerHTML=`<div class="ws-usage-filters">${select('Month','usage-month',months,months[0][0])}${select('Project','usage-project',[['','All projects'],...W.records('project').map(p=>[p.id,e(p.title)])],'')}<button id="usage-refresh" class="icon-button" aria-label="Refresh usage">${icon('history')}</button><button id="usage-export" class="button">${icon('download')}Export CSV</button></div>`+credits()+`<div id="usage-stats"></div>`+card('Development activity','Daily activity in UTC. Browser builds and tests are not billable.',`<div class="ws-segment"><button class="selected" data-series="build">Builds</button><button data-series="test">Tests</button></div><div id="activity-chart"></div><p class="muted">Activity is reported by your browser and may be incomplete. Storage shows current saved source, regardless of the selected month.</p>`)+card('Recent activity','Activity from your selected month and project.','<div id="recent-activity" aria-live="polite">Loading activity…</div>');
      let activity=[],series='build';const filtered=()=>activity.filter(x=>x.at.startsWith(root.querySelector('#usage-month').value)&&(!root.querySelector('#usage-project').value||(x.projectId===root.querySelector('#usage-project').value||W.get(x.projectId)?.workspace?.parentId===root.querySelector('#usage-project').value)));
      function paint(){if(!root.querySelector('#usage-stats'))return;const rows=filtered(),projects=W.records('project'),files=projects.flatMap(p=>Object.values(p.codeDraft||p.files||{})),bytes=new TextEncoder().encode(files.join('')).length;root.querySelector('#usage-stats').innerHTML=`<div class="ws-stat-grid">${[['Browser builds',rows.filter(x=>x.kind==='build').length,'Recorded this month'],['Unit test runs',rows.filter(x=>x.kind==='test').length,'Recorded this month'],['Saved projects',projects.length,'Current project count'],['Source storage',bytes<1024?bytes+' B':Math.round(bytes/1024)+' KB',files.length+' saved text files']].map(([title,value,copy])=>`<div class="settings-card"><h3>${title}</h3><strong class="ws-stat">${value}</strong><small>${copy}</small></div>`).join('')}</div>`;
        const [year,month]=root.querySelector('#usage-month').value.split('-').map(Number),days=new Date(Date.UTC(year,month,0)).getUTCDate(),counts=Array.from({length:days},(_,i)=>rows.filter(x=>x.kind===series&&new Date(x.at).getUTCDate()===i+1).length),max=Math.max(1,...counts);root.querySelector('#activity-chart').innerHTML=`<div class="ws-chart" role="img" aria-label="${e(series)} activity by day. ${counts.reduce((a,b)=>a+b,0)} runs this month.">${counts.map((c,i)=>`<div title="Day ${i+1}: ${c} ${series}s"><i style="height:${c/max*100}%"></i><small>${i===0||i===14||i===days-1?i+1:''}</small></div>`).join('')}</div>${counts.some(Boolean)?'':'<p>No recorded '+series+'s in this period. Run a project or its tests to start tracking activity.</p>'}`;
        root.querySelector('#recent-activity').innerHTML=rows.length?`<div class="ws-table-wrap"><table><thead><tr><th>Activity</th><th>Project</th><th>Status</th><th>Date</th></tr></thead><tbody>${rows.slice(0,50).map(x=>`<tr><td>${e({build:'Browser build',test:'Unit tests',project:'Project created',ai:'AI request'}[x.kind]||x.kind)}</td><td>${e(W.get(x.projectId)?.title||'Deleted project')}</td><td>${x.success?'Completed':'Failed'}</td><td>${e(new Date(x.at).toLocaleString())}</td></tr>`).join('')}</tbody></table></div>`:'<div class="ws-empty"><h3>Your activity will appear here</h3><p>Create a project, build a preview or run its tests.</p></div>';
      }
      const load=async()=>{activity=await W.loadActivity();paint();};bind('usage-refresh',load);root.querySelectorAll('#usage-month,#usage-project').forEach(n=>n.onchange=paint);root.querySelectorAll('[data-series]').forEach(b=>b.onclick=()=>{series=b.dataset.series;root.querySelectorAll('[data-series]').forEach(n=>n.classList.toggle('selected',n===b));paint();});bind('usage-export',()=>{const csv=[['Activity','Project','Success','Date'],...filtered().map(x=>[x.kind,W.get(x.projectId)?.title||'',x.success,x.at])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');W.download('draftmango-activity.csv',csv,'text/csv');});load().catch(error=>{root.querySelector('#recent-activity').textContent=error.message;});
    }else if(tab==='billing'){
      await globalThis.DraftmangoBilling.render(content);
    }else if(tab==='cli'){
      content.innerHTML=card('Build from your terminal','Connect a local repository, run builds and tests on your computer, and review proposed changes before applying them.',`<div class="ws-inset"><h3>${icon('terminal')} Draftmango CLI <span class="ws-badge">Coming soon</span></h3><p>Terminal pairing is not available yet. For now, download your project source to work in your own editor. <a class="text-link" href="/help#exports">Learn about local work and exports</a>.</p><div class="ws-action-row"><a class="button" href="#cli">View local tasks</a><a class="button" href="#device">Approve a terminal code</a></div></div>`)+card('Authorized CLI devices','Revoke a device to end its access to your account. Revocation does not delete files on that computer.',`<div class="ws-empty"><p>No terminals are connected yet.</p><small>Device pairing will become available with the Draftmango CLI.</small></div>`);
    }else{
      content.innerHTML=card('Export your account','Take a portable copy of your profile, saved preferences, chats, project details and source files.',`<div class="ws-inset"><strong>Your work belongs with you.</strong><p>Download a JSON archive. Export daily activity from Usage. Account passwords and service credentials are excluded. Review the archive: secrets added to your own files or messages may still be included.</p><button class="button primary" id="export-account">${icon('download')}Export account data</button></div>`)+card('Privacy and account data','Your saved preferences, chats and project data are tied to your signed-in account.',`<p>Browser build and test activity records counts and status, not source code, prompts or test output. It is not used to calculate charges. AI requests send the submitted prompt, references and project files to the configured provider.</p><p>Domain drafts and a working copy of your projects are stored on this device.</p><div class="ws-action-row"><a href="/legal#privacy" class="text-link">Privacy policy ${icon('external')}</a><a href="/legal#terms" class="text-link">Terms of service ${icon('external')}</a><a href="/help#data" class="text-link">Saved work &amp; privacy help ${icon('external')}</a></div>`)+card('Delete your account','Permanently remove your Draftmango profile, saved chats and projects, preferences and activity.',`<p>Export your work first. This cannot be undone. Downloaded files and copies on other devices are not erased. See the privacy notice for recovery copies and other retained records.</p><button id="delete-account" class="button danger">Delete account</button>`,'danger-card');
      bind('export-account',async()=>{await A.sync();const data=await A.request('/api/accounts/export');data.deviceDomainDrafts=JSON.parse(localStorage.getItem(A.key('domains'))||'[]');data.deviceWorkingCopy=W.library();W.download('draftmango-account.json',JSON.stringify(data,null,2));});
      bind('delete-account',()=>W.dialog('Delete your account?',`<p>Your chats, projects and source files will be permanently deleted. This cannot be undone.</p>${field('Current password','delete-password','','password','required autocomplete="current-password"')}${field('Type DELETE MY ACCOUNT','delete-confirmation','','text','required autocomplete="off"')}`,{label:'Permanently delete',submit:async d=>{await A.request('/api/accounts/delete',{method:'POST',body:{password:d.querySelector('#delete-password').value,confirmation:d.querySelector('#delete-confirmation').value}});for(const key of Object.keys(localStorage))if(key.includes(':account:django:'+A.user.id))localStorage.removeItem(key);A.sessionChanged();location.replace('/auth#mode=signup');}}));
    }
  }
  function credits(){return card('Your AI credits','Account-wide balance. Manual editing and browser previews are free.',`<div class="ws-setting-row"><h3>Free <span class="ws-badge">Billing not connected</span></h3><a class="text-link" href="#settings/billing">Plans & credits ${icon('arrow')}</a></div><div class="ws-stat-grid"><div><strong class="ws-stat">—</strong><small>Available credits</small></div><div><strong class="ws-stat">—</strong><small>Reserved for running tasks</small></div><div><strong class="ws-stat">—</strong><small>Used from current allowances</small></div></div><div class="ws-key-values"><div><span>Monthly credits</span><strong>Not issued</strong></div><div><span>Purchased credits</span><strong>Not issued</strong></div><div><span>Trial credits</span><strong>500 planned at launch</strong></div></div><p class="muted">Credit metering is not active in this local workspace. AI usage is billed to the configured provider account. No balance or deduction is simulated here.</p>`);}
  globalThis.DraftmangoSettings={render};
})();
